package com.silverroom.camera;
import android.app.*;
import android.content.ClipData;
import android.graphics.drawable.GradientDrawable;
import android.os.Bundle;
import android.view.*;
import android.widget.*;
import java.util.*;
import static com.silverroom.camera.Controls.*;

/** Dedicated ordered shelf. Only its own drag token is accepted; originals are never touched. */
final class FavoritesPicker extends ThemedDialog {
    interface Change{void changed(List<Integer> ids);}
    private final Activity owner;private final Change change;private List<Integer> ids;private LinearLayout list;private ScrollView scroll;private final Object dragToken=new Object();private int dragging=-1;private final Map<Integer,View> rows=new HashMap<>();
    FavoritesPicker(Activity a,List<Integer> pins,Change c){super(a);owner=a;ids=new ArrayList<>(pins);change=c;}
    int dp(int n){return Math.round(n*owner.getResources().getDisplayMetrics().density);}
    int target(){return UiSpec.toolHeight(owner.getResources().getConfiguration().fontScale);}
    TextView text(String s,int size,int color){TextView t=new TextView(owner);t.setText(s);t.setTextSize(Math.max(UiSpec.CAPTION,size));t.setFontFeatureSettings("tnum");t.setTextColor(color);t.setGravity(Gravity.CENTER);t.setIncludeFontPadding(false);return t;}
    void save(){change.changed(new ArrayList<>(ids));}
    void move(int id,int target){int from=ids.indexOf(id);target=Math.max(0,Math.min(ids.size()-1,target));if(from<0||from==target)return;ids=FilterShelf.move(ids,from,target);View row=rows.get(id);list.removeView(row);list.addView(row,target);}
    void render(){list.removeAllViews();rows.clear();if(ids.isEmpty()){TextView empty=text("暂无收藏\n在胶片库点 ☆ 添加喜欢的风格",14,MUTED);list.addView(empty,new LinearLayout.LayoutParams(-1,dp(120)));return;}for(int id:ids){LinearLayout row=new LinearLayout(owner);row.setGravity(Gravity.CENTER_VERTICAL);TextView handle=text("☰",21,AMBER);handle.setContentDescription("拖动排序："+FilmCatalog.NAMES[id]+"，点击可上下移动");row.addView(handle,new LinearLayout.LayoutParams(dp(target()),-1));TextView title=text(FilmCatalog.NAMES[id],13,CREAM);title.setGravity(Gravity.CENTER_VERTICAL);title.setMaxLines(2);row.addView(title,new LinearLayout.LayoutParams(0,-1,1));TextView remove=text("×",22,MUTED);remove.setContentDescription("取消收藏："+FilmCatalog.NAMES[id]);row.addView(remove,new LinearLayout.LayoutParams(dp(target()),-1));remove.setOnClickListener(v->{ids.remove(Integer.valueOf(id));render();save();});handle.setOnTouchListener((v,e)->{if(e.getActionMasked()==MotionEvent.ACTION_DOWN){dragging=id;boolean begun=v.startDragAndDrop(ClipData.newPlainText("favorite",String.valueOf(id)),new View.DragShadowBuilder(row),dragToken,0);if(begun){v.performHapticFeedback(HapticFeedbackConstants.LONG_PRESS);return true;}}return false;});handle.setOnClickListener(v->{PopupMenu menu=new PopupMenu(ThemeUi.context(owner),handle);menu.getMenu().add("上移").setOnMenuItemClickListener(item->{move(id,ids.indexOf(id)-1);save();return true;});menu.getMenu().add("下移").setOnMenuItemClickListener(item->{move(id,ids.indexOf(id)+1);save();return true;});menu.show();});list.addView(row,new LinearLayout.LayoutParams(-1,dp(Math.max(62,target()))));rows.put(id,row);}}
    @Override protected void onCreate(Bundle b){super.onCreate(b);requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout root=new LinearLayout(owner);root.setOrientation(1);root.setPadding(dp(16),dp(12),dp(16),dp(16));GradientDrawable bg=new GradientDrawable();bg.setColor(INK);bg.setCornerRadius(dp(UiSpec.RADIUS));root.setBackground(bg);LinearLayout head=new LinearLayout(owner);TextView title=text("收藏排序",20,CREAM);title.setGravity(Gravity.CENTER_VERTICAL);head.addView(title,new LinearLayout.LayoutParams(0,dp(target()),1));TextView done=text("完成",14,AMBER);head.addView(done,new LinearLayout.LayoutParams(dp(56),dp(target())));done.setOnClickListener(v->dismiss());root.addView(head);root.addView(text("拖动左侧手柄排序 · 主页面收藏滚轮同步",11,MUTED),new LinearLayout.LayoutParams(-1,-2));scroll=new ScrollView(owner);list=new LinearLayout(owner);list.setOrientation(1);scroll.addView(list);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));scroll.setOnDragListener((v,e)->{if(e.getLocalState()!=dragToken)return false;switch(e.getAction()){case DragEvent.ACTION_DRAG_STARTED:return true;case DragEvent.ACTION_DRAG_LOCATION:move(dragging,(int)((e.getY()+scroll.getScrollY())/dp(Math.max(62,target()))));if(e.getY()<dp(target()))scroll.scrollBy(0,-dp(14));else if(e.getY()>scroll.getHeight()-dp(target()))scroll.scrollBy(0,dp(14));return true;case DragEvent.ACTION_DROP:return true;case DragEvent.ACTION_DRAG_ENDED:dragging=-1;save();return true;default:return true;}});render();setContentView(root);getWindow().setBackgroundDrawableResource(android.R.color.transparent);getWindow().setGravity(Gravity.BOTTOM);getWindow().setLayout(-1,Math.round(owner.getResources().getDisplayMetrics().heightPixels*.72f));}
}
